import itertools

def check_n_exhaustive(n):
    # For n=5, M=10.
    # y_1=0. y_5 <= 10.
    for y in itertools.combinations(range(1, 15), n-1):
        Y = [0] + list(y)
        sums = []
        for i in range(n):
            for j in range(i+1, n):
                sums.append(Y[i] + Y[j])
        sums.sort()
        # Check if sums are 1, 2, ..., 10 (or any AP)
        if len(set(sums)) == n*(n-1)//2:
            if sums[-1] - sums[0] == len(sums) - 1:
                return Y
    return None

print(f"n=5: {check_n_exhaustive(5)}")

